function mimeTypeConvert(value) {
    let inputTypes;
    const acceptTypes = [];
    if (isArray(value)) {
        inputTypes = value;
    }
    else if (isString(value)) {
        inputTypes = value.split(',');
    }
    else {
        inputTypes = [];
    }
    if (inputTypes.length > 0) {
        inputTypes.forEach(n => {
            if (MIME_Map[n]) {
                acceptTypes.push(MIME_Map[n]);
            }
            else {
                acceptTypes.push(n);
            }
        });
    }
    return acceptTypes.join(',');
}

